/*
 * A201474  Primes of the form 2n^2 + 5.
 * https://oeis.org/A201474
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 7, u16 n <= 45, u32 n <= 59, u64 n <= 5000,
 *            u128 n <= 5000, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A201474: primes of the form 2*n^2 + 5, generated by checking each n from 0 upward */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"  // provides: bool is_prime_big(seq_t n);

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;          // cached primes
    static idx_t cache_size = 0;         // number of cached primes
    static idx_t cache_cap = 0;          // capacity of cache array
    static idx_t last_k = 0;             // next k to test (k starts from 0)

    // Ensure we have at least n primes cached
    while (cache_size < n) {
        // Compute the value 2*k^2 + 5 in seq_t arithmetic
        idx_t k = last_k;
        seq_t val = (seq_t)k * (seq_t)k * 2 + 5;

        // Test primality
        if (is_prime_big(val)) {
            // Grow cache if needed
            if (cache_size == cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 16;
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp) abort();
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_size++] = val;
        }

        last_k++;  // next k to test
    }

    // Return the (n-1)-th element (0‑based indexing)
    return cache[n - 1];
}
